def circular_shift(x, shift):
    digits = [int(d) for d in str(x))]
    n = len(digits)
    if shift >= n:
        return ''.join(str(d) for d in digits[::-1]))
    else:
        shift %= n
        return ''.join(str(d) for d in digits[-shift:] + digits[:-shift]))

def pluck(arr):
    if not arr:
        return []
    smallest_even = float('inf')
    smallest_index = float('inf')
    for i, x in enumerate(arr):
        if x % 2 == 0 and x < smallest_even:
            smallest_even = x
            smallest_index = i
        elif x % 2 == 0 and x == smallest_even and i < smallest_index:
            smallest_index = i
    return [smallest_even, smallest_index] if smallest_even != float('inf') else []

